package store

// Written by hand (not generated by sqlc): the item list combines optional
// filters and a direction, which sqlc cannot express without defeating the
// indexes.

import (
	"context"
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// StreamQuery selects a page of items.
type StreamQuery struct {
	FeedID    *int64 // only this feed
	GroupID   *int64 // only feeds in this group
	SavedOnly bool
	// Search keeps the items that have these words (see search_query in
	// the migrations).
	Search      string
	UnreadOnly  bool
	OldestFirst bool
	After       *Cursor // continue after this item
	Limit       int
}

// Cursor is a position in a list ordered by (time, id): item lists use
// published_at, which stays stable while items are marked read, and the list
// of changes uses state_changed_at.
type Cursor struct {
	Time time.Time
	ID   int64
}

// String encodes the cursor for the API ("<unix microseconds>.<id>").
func (c Cursor) String() string {
	return strconv.FormatInt(c.Time.UnixMicro(), 10) + "." + strconv.FormatInt(c.ID, 10)
}

// ParseCursor decodes Cursor.String.
func ParseCursor(s string) (Cursor, error) {
	micros, id, ok := strings.Cut(s, ".")
	if !ok {
		return Cursor{}, fmt.Errorf("invalid cursor %q", s)
	}
	us, err1 := strconv.ParseInt(micros, 10, 64)
	n, err2 := strconv.ParseInt(id, 10, 64)
	if err1 != nil || err2 != nil {
		return Cursor{}, fmt.Errorf("invalid cursor %q", s)
	}
	return Cursor{Time: time.UnixMicro(us), ID: n}, nil
}

type StreamItem struct {
	ID          int64
	FeedID      int64
	Title       string
	Url         string
	Author      string
	Content     string
	PublishedAt time.Time
	Read        bool
	Saved       bool
}

func (q *Queries) ItemStream(ctx context.Context, s StreamQuery) ([]StreamItem, error) {
	var where []string
	var args []any
	arg := func(v any) string {
		args = append(args, v)
		return "$" + strconv.Itoa(len(args))
	}
	if s.FeedID != nil {
		where = append(where, "i.feed_id = "+arg(*s.FeedID))
	}
	if s.GroupID != nil {
		where = append(where, "i.feed_id IN (SELECT feed_id FROM feed_groups WHERE group_id = "+arg(*s.GroupID)+")")
	}
	if s.SavedOnly {
		where = append(where, "i.saved_at IS NOT NULL")
	}
	with, from := "", "items i"
	if s.Search != "" {
		// The matching items first, from the index, then their page. Left
		// to choose, PostgreSQL may instead walk all items newest first,
		// reading each item's words on the way to the few that match.
		with = "WITH found AS MATERIALIZED (SELECT item_id FROM item_search WHERE search @@ search_query(" + arg(s.Search) + ")) "
		from = "found f JOIN items i ON i.id = f.item_id"
	}
	if s.UnreadOnly {
		where = append(where, "i.read_at IS NULL")
	}
	op, dir := "<", "DESC"
	if s.OldestFirst {
		op, dir = ">", "ASC"
	}
	if s.After != nil {
		where = append(where, fmt.Sprintf("(i.published_at, i.id) %s (%s, %s)", op, arg(s.After.Time), arg(s.After.ID)))
	}

	var sql strings.Builder
	sql.WriteString(with + `SELECT i.id, i.feed_id, i.title, i.url, i.author, i.content, i.published_at,
	                        i.read_at IS NOT NULL, i.saved_at IS NOT NULL
	                 FROM ` + from)
	if len(where) > 0 {
		sql.WriteString(" WHERE " + strings.Join(where, " AND "))
	}
	fmt.Fprintf(&sql, " ORDER BY i.published_at %s, i.id %s LIMIT %s", dir, dir, arg(s.Limit))

	if s.Search != "" {
		// Planned with the words searched for, never with a plan made for
		// any words: search_query is then worked out once, while planning,
		// not for each row the plan may read.
		args = append([]any{pgx.QueryExecModeExec}, args...)
	}
	rows, err := q.db.Query(ctx, sql.String(), args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StreamItem
	for rows.Next() {
		var it StreamItem
		if err := rows.Scan(&it.ID, &it.FeedID, &it.Title, &it.Url, &it.Author, &it.Content,
			&it.PublishedAt, &it.Read, &it.Saved); err != nil {
			return nil, err
		}
		items = append(items, it)
	}
	return items, rows.Err()
}
